import sys
input = sys.stdin.readline

def solve():
	n = int(input())
	a = list(map(int, input().split()))
	w = [False] * (n + 1)
	b = [None] * n
	for i in range(n):
		j = a[i]
		if not w[j]:
			w[j] = True
			b[i] = j
	c = []
	for i in range(1, n + 1):
		if not w[i]:
			c.append(i)
	for i in range(n):
		j = b[i]
		if j is None:
			if c[-1] != i + 1:
				b[i] = c.pop()
			elif len(c) != 1:
				c.pop()
				b[i] = c.pop()
				c.append(i + 1)
			else:
				v = a[i]
				for j in range(n):
					if b[j] == v:
						b[j] = i + 1
						b[i] = a[i]
						break
	r = 0
	for i in range(n):
		r += a[i] == b[i]
	print(r)
	print(' '.join(map(str, b)))
for i in range(int(input())):
	solve()
